// One-time move of CCTV positions from the first traced floor plans to the
// wall-only plans generated by tools/extract_walls.py (October 2026).
//
// Positions are stored as percentages of the plan, and the two plans frame the
// PDF differently. Both frames are expressed in PDF points (measured by aligning
// the old SVG on the PDF), so every point maps exactly:
//   pdf = origin + percent / 100 * size        (old frame)
//   percent' = (pdf - origin') / size' * 100   (new frame)
// A settings flag makes this run once; floors with an imported custom SVG keep
// their positions, because those positions belong to that custom plan.

const FLAG = 'map_frame';
const VERSION = 'walls-2026-10';
const FRAMES = {
  gf: { from: { x: 57.75, y: 309.5, w: 990.4, h: 128.4 }, to: { x: 30, y: 292, w: 1142, h: 170 } },
  ff: { from: { x: 126.0, y: 251.25, w: 623.3, h: 88.1 }, to: { x: 126, y: 230, w: 624, h: 110 } },
};

function convert(frame, x, y) {
  const pdfX = frame.from.x + (x / 100) * frame.from.w;
  const pdfY = frame.from.y + (y / 100) * frame.from.h;
  const clamp = (value) => Math.max(0, Math.min(100, Number(value.toFixed(3))));
  return { x: clamp(((pdfX - frame.to.x) / frame.to.w) * 100), y: clamp(((pdfY - frame.to.y) / frame.to.h) * 100) };
}

async function remapFloorplans(pool) {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    await client.query('LOCK TABLE settings IN EXCLUSIVE MODE');
    const flag = (await client.query('SELECT setting_value FROM settings WHERE setting_key = $1', [FLAG])).rows[0];
    if (flag?.setting_value === VERSION) {
      await client.query('COMMIT');
      return { skipped: true, moved: 0 };
    }
    const custom = new Set((await client.query("SELECT setting_key FROM settings WHERE setting_key LIKE 'map:%'")).rows.map((row) => row.setting_key.slice(4)));
    const cameras = (await client.query('SELECT id, map_x, map_y, details FROM cameras')).rows;
    let moved = 0;
    for (const camera of cameras) {
      const floor = camera.details?.floor === 'ff' ? 'ff' : 'gf';
      if (custom.has(floor) || camera.map_x === null || camera.map_y === null) continue;
      const next = convert(FRAMES[floor], Number(camera.map_x), Number(camera.map_y));
      await client.query('UPDATE cameras SET map_x = $1, map_y = $2 WHERE id = $3', [next.x, next.y, camera.id]);
      moved += 1;
    }
    await client.query(
      `INSERT INTO settings (setting_key, setting_value, updated_at) VALUES ($1, $2, now())
       ON CONFLICT (setting_key) DO UPDATE SET setting_value = EXCLUDED.setting_value, updated_at = now()`,
      [FLAG, JSON.stringify(VERSION)],
    );
    await client.query('COMMIT');
    return { skipped: false, moved };
  } catch (error) {
    await client.query('ROLLBACK').catch(() => {});
    throw error;
  } finally {
    client.release();
  }
}

module.exports = { FRAMES, VERSION, convert, remapFloorplans };
